HTML=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pingora</title><style>
*{box-sizing:border-box}body{margin:0;background:#080a11;color:#eef0f8;font:14px system-ui,sans-serif}button,input,textarea{font:inherit}.app{height:100vh;display:grid;grid-template-columns:310px 1fr 250px;background:radial-gradient(circle at 60% 0,#24204b,#0b0d16 42%,#080a11 75%)}aside{background:#0b0e16e8;border-color:#202432}.side{border-right:1px solid #202432;padding:20px 13px;display:flex;flex-direction:column}.brand{font-size:21px;font-weight:800;display:flex;gap:10px;align-items:center;padding:0 10px 18px}.logo{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(135deg,#8b5cf6,#4f7cff)}.me,.chat{display:flex;align-items:center;gap:10px;padding:10px;border-radius:14px}.me{background:#111520;border:1px solid #232738}.avatar{width:43px;height:43px;flex:none;border-radius:14px;display:grid;place-items:center;font-weight:800;font-size:12px;background:linear-gradient(135deg,#7c5cff,#3f7cff)}small{color:#858ca3;font-size:11px;display:block}.search{margin:12px 0;background:#111520;border:1px solid #24283a;border-radius:13px;padding:10px;color:#858ca3}.search input{border:0;outline:0;background:none;color:white;width:90%}.chat{width:100%;border:0;background:none;color:white;text-align:left;cursor:pointer}.chat:hover,.chat.active{background:#171a28}.meta{min-width:0;flex:1}.top,.bottom{display:flex;justify-content:space-between;gap:7px}.bottom{color:#777e92;font-size:11px}.bottom span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.new{margin-top:auto;background:#171a27;border:1px solid #2a2e40;color:#ddd;border-radius:13px;padding:11px;cursor:pointer}.main{min-width:0;display:flex;flex-direction:column}.head{height:76px;border-bottom:1px solid #202432;display:flex;justify-content:space-between;align-items:center;padding:0 24px;background:#0c0f18cc}.person{display:flex;align-items:center;gap:10px}.actions button,.attach,.emoji{background:none;border:0;color:#9299ad;cursor:pointer}.messages{flex:1;overflow:auto;padding:28px 6vw;display:flex;flex-direction:column;gap:9px}.msg{max-width:72%;animation:pop .2s}.mine{align-self:flex-end}.bubble{background:#151925;border:1px solid #25293a;padding:10px 13px;border-radius:16px 16px 16px 5px;line-height:1.45}.mine .bubble{background:linear-gradient(135deg,#6046bf,#5162dc);border-color:#7560df;border-radius:16px 16px 5px 16px}.foot{text-align:right;font-size:9px;color:#7c8398;margin-top:4px}.mine .foot{color:#d8dcff}.typing{height:0;opacity:0;padding-left:6vw;color:#858ca0;font-size:11px;transition:.2s}.typing.show{height:24px;opacity:1}.composer{display:flex;gap:8px;align-items:center;padding:12px 24px 18px}.input{flex:1;background:#121520;border:1px solid #282c3c;border-radius:17px;padding:4px 10px 4px 14px;display:flex}.input textarea{flex:1;resize:none;background:none;border:0;outline:0;color:white;padding:9px}.send{width:42px;height:42px;border:0;border-radius:14px;background:linear-gradient(135deg,#805cff,#4f73ff);color:white;cursor:pointer}.details{border-left:1px solid #202432;padding:35px 20px;text-align:center}.details .avatar{width:76px;height:76px;margin:auto;border-radius:24px}.pill{display:inline-block;margin:10px;background:#111821;border:1px solid #242b37;padding:6px 10px;border-radius:20px;color:#98a0b4;font-size:10px}.section{text-align:left;border-top:1px solid #202432;padding-top:18px;margin-top:18px;color:#7f869b}.modal{position:fixed;inset:0;background:#0009;display:none;place-items:center}.modal.open{display:grid}.card{background:#121520;border:1px solid #2a2e40;border-radius:20px;padding:25px;width:min(380px,90vw)}@keyframes pop{from{opacity:0;transform:translateY(5px)}to{opacity:1}}@media(max-width:1050px){.app{grid-template-columns:280px 1fr}.details{display:none}}@media(max-width:700px){.app{display:block}.side{display:none}.head{padding:0 14px}.messages{padding:20px 14px}.composer{padding:10px 12px}.msg{max-width:86%}}
</style></head><body><div class="app">
<aside class="side"><div class="brand"><span class="logo">P</span>Pingora</div><div class="me"><div class="avatar">YO</div><div><b>You</b><small>Available</small></div></div><div class="search">⌕ <input id="search" placeholder="Search chats..."></div><div id="list">{% for c in chats %}<button class="chat {% if loop.first %}active{% endif %}" data-id="{{c.id}}"><div class="avatar">{{c.avatar}}</div><div class="meta"><div class="top"><b>{{c.name}}</b><small>{{c.time}}</small></div><div class="bottom"><span>{{c.messages[-1].text if c.messages else "Start a conversation"}}</span></div></div></button>{% endfor %}</div><button class="new" id="new">＋ New chat</button></aside>
<main class="main"><header class="head"><div class="person"><div class="avatar" id="ha">MC</div><div><b id="hn">Maya Chen</b><small>● <span id="hs">Online</span></small></div></div><div class="actions">⌕　•••</div></header><section class="messages" id="messages"></section><div class="typing" id="typing">••• Maya is typing…</div><div class="composer"><button class="attach" id="attach">＋</button><div class="input"><textarea id="input" rows="1" placeholder="Write a message..."></textarea><button class="emoji" id="emoji">☺</button></div><button class="send" id="send">➤</button></div></main>
<aside class="details"><div class="avatar" id="da">MC</div><h2 id="dn">Maya Chen</h2><small id="du">@mayachen</small><div class="pill">● <span id="ds">Online</span></div><div class="section">ABOUT<p>Designing useful things and collecting good ideas.</p></div><div class="section">SHARED MEDIA<p>IMG　 PDF　 ZIP</p></div></aside></div>
<script>
let chats={{chats|tojson}},cur=chats[0],M=document.getElementById('messages');
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function render(){M.innerHTML=cur.messages.length?cur.messages.map(m=>'<div class="msg '+(m.sender==='me'?'mine':'')+'"><div class="bubble">'+esc(m.text)+'<div class="foot">'+m.time+(m.sender==='me'?'　✓✓':'')+'</div></div></div>').join(''):'<div style="margin:auto;color:#777">Start the conversation ✨</div>';M.scrollTop=M.scrollHeight}
function select(id){cur=chats.find(c=>c.id==id)||cur;document.querySelectorAll('.chat').forEach(x=>x.classList.toggle('active',x.dataset.id==cur.id));ha.textContent=cur.avatar;hn.textContent=cur.name;hs.textContent=cur.status;da.textContent=cur.avatar;dn.textContent=cur.name;du.textContent=cur.username;ds.textContent=cur.status;render()}
async function send(){let i=input,t=i.value.trim();if(!t)return;let r=await fetch('/api/message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:cur.id,text:t})}),d=await r.json();if(d.ok){cur.messages.push(d.message);i.value='';render()}}
document.querySelectorAll('.chat').forEach(x=>x.onclick=()=>select(x.dataset.id));send.onclick=send;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};emoji.onclick=()=>{input.value+=' 😊';input.focus()};search.oninput=e=>document.querySelectorAll('.chat').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(e.target.value.toLowerCase())?'flex':'none');new.onclick=async()=>{let n=prompt('Username or chat name:');if(n){await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:n})});location.reload()}};setTimeout(()=>typing.classList.add('show'),1000);setTimeout(()=>typing.classList.remove('show'),4000);select(1);
</script></body></html>'''
@app.get("/")
def index(): return render_template_string(HTML,chats=chats)
@app.post("/api/message")
def message():
 d=request.get_json() or {}; c=next((x for x in chats if x["id"]==int(d.get("chat_id",1))),None); t=str(d.get("text","")).strip()
 if not c or not t:return jsonify(ok=False),400
 m={"id":max([x["id"] for x in c["messages"]]+[0])+1,"sender":"me","text":t,"time":"now","state":"sent"};c["messages"].append(m);return jsonify(ok=True,message=m)
@app.post("/api/chat")
def chat():
 d=request.get_json() or {};n=str(d.get("name","New Chat")).strip() or "New Chat";c={"id":max(x["id"] for x in chats)+1,"name":n,"username":"@newchat","avatar":n[:2].upper(),"status":"Online","time":"now","messages":[]};chats.insert(0,c);return jsonify(ok=True,chat=c)
if __name__=="__main__":app.run(host="0.0.0.0",port=5000,debug=True)
